# Standard library
import uuid

# Third-party
from sqlalchemy import Text, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, ReferenceBaseMixin


class CoreRefResourceType(Base, ReferenceBaseMixin):
    __tablename__ = "core_ref_resource_type"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        comment=(
            "Primary key UUID, auto-generated by the database. Uniquely "
            "identifies a resource type used by the access policy system."
        ),
    )
    key: Mapped[str] = mapped_column(
        Text,
        unique=True,
        nullable=False,
        comment=(
            "Machine-readable slug identifying this resource type "
            "(e.g. 'gear', 'poi', 'ref'). Used by the resource_access "
            "dependency to look up policies."
        ),
    )
